<div class="page-title clearfix"><h1>Marketing Contacts</h1><div class="title-button-group"><a class="btn btn-default" href="<?php echo site_url('email_marketing/dashboard'); ?>">Dashboard</a><a class="btn btn-default" href="<?php echo site_url('email_marketing/contacts/export'); ?>">Export contacts</a><a class="btn btn-primary" href="<?php echo site_url('email_marketing/create'); ?>">Create campaign / CSV import</a></div></div>
<div class="alert alert-info">This list contains consent records. Campaign selection still requires Opted In and excludes suppression and Do Not Contact records.</div>
<div class="card"><div class="card-body"><form method="get" action="<?php echo site_url('email_marketing/contacts'); ?>" class="form-inline"><input class="form-control" name="q" value="<?php echo esc($q); ?>" placeholder="Search name, company, email"><button class="btn btn-default ml10">Search</button></form></div><div class="table-responsive"><table class="table"><thead><tr><th>Contact</th><th>Email</th><th>Consent</th><th>Location</th><th>Updated</th><th>Action</th></tr></thead><tbody><?php foreach($contacts as $c): ?><tr><td><?php echo esc(trim(($c->first_name??'').' '.($c->last_name??''))?:($c->company_name??'')); ?></td><td><?php echo esc($c->email); ?></td><td><?php echo esc($c->consent); ?></td><td><?php echo esc(trim(($c->state??'').' '.($c->city??'').' '.($c->zip??''))); ?></td><td><?php echo esc($c->updated_at??''); ?></td><td><a href="<?php echo site_url('email_marketing/consent/'.$c->entity_type.'/'.$c->entity_id); ?>">Edit consent</a></td></tr><?php endforeach; if(!$contacts): ?><tr><td colspan="6">No CRM contacts found.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card mt15"><div class="card-header"><h4>Suppression list</h4></div><table class="table"><thead><tr><th>Email</th><th>Reason</th><th>Created</th></tr></thead><tbody><?php foreach($suppressed as $s): ?><tr><td><?php echo esc($s->email); ?></td><td><?php echo esc($s->reason); ?></td><td><?php echo esc($s->created_at); ?></td></tr><?php endforeach; if(!$suppressed): ?><tr><td colspan="3">No suppressed contacts.</td></tr><?php endif; ?></tbody></table></div>
